import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import Layout from "../components/Layout";
import FloorPlansX from "../ppm/primitives/floor-plans/floor-plans-x";
import PropertyGalleryX, {
  demoGallery,
} from "../ppm/primitives/gallery/property-gallery-x";
import PropertyOverviewX from "../ppm/primitives/overview/property-overview-x";
import Seo from "../components/Seo";
import NotFoundPage from "../components/NotFoundPage";
import { featuredImage, isPublished } from "../ppm/modules/property/derive";
import { useCatalogue } from "../ppm/primitives/property/useCatalogue";
import { propertySlug } from "../ppm/modules/property/catalogueRules";
import { resolveProperty } from "../ppm/primitives/property/property-images";
import SimilarProperties from "../ppm/primitives/property/similar-properties";
import PropertyHeroX from "../ppm/primitives/property-hero/property-hero-x";

import type { PropertyRecord } from "../ppm/modules/property/types";

/**
 * What gatsby-node hands this page.
 *
 * `property` is the whole record. It arrives that way because a property
 * created in the CMS does not exist in property-data.ts, and an EDITED sample
 * exists there only in its pre-edit form — so looking it up here would render
 * the wrong copy in one case and nothing at all in the other.
 *
 * The lookup below is kept as a fallback for pages built before this changed.
 */
type Context = { slug?: string; property?: PropertyRecord };

/**
 * The property detail page.
 *
 * One template for every property — a page is created per record in
 * gatsby-node and looked up here by slug. There is never a per-property
 * component.
 *
 * The order answers the questions a renter asks, in order: which property is
 * this, what does it look like, what can I rent, what is living here like,
 * what else might suit me.
 */
export default function PropertyPage({ pageContext, location }: PageProps<object, Context>) {
  const { data, ready, error } = useCatalogue();
  const slug = propertySlug(location.pathname) ?? pageContext.slug;
  const property = data.find((item) => item.slug === slug);

  // A page only exists because a published record did, so both checks are
  // defensive rather than expected — but a blank page is a better failure
  // than a crash, or than a draft going live. The second check still matters:
  // it is what keeps a property that was unpublished or deleted since the
  // last build from rendering if its page is still cached somewhere.
  if (!property || !isPublished(property)) {
    if (!ready || error) return <Layout><p role="status" style={{ padding: "3rem" }}>
      {error ? "Property details are temporarily unavailable. Please try again shortly." : "Loading property details…"}
    </p></Layout>;
    return <NotFoundPage />;
  }

  /* Composed once, here, so every section below shows the same photographs and
     the hero's "View N Photos" counts what the gallery will actually display.
     The record's own images when it has them; the shared demo set while the
     bundled listings do not. The count used to be a hand-typed number on the
     record — several claimed eighteen while the gallery rendered eight, so the
     control made a promise the next click broke. */
  const images = property.images?.length ? property.images : demoGallery;
  const withImages = { ...property, images };

  return (
    <Layout>
      <PropertyHeroX property={withImages} />
      <PropertyGalleryX images={images} />
      <div id="floor-plans">
        <FloorPlansX slug={property.slug} plans={property.floorPlans} />
      </div>
      <PropertyOverviewX property={withImages} />
      <SimilarProperties current={property} />
    </Layout>
  );
}

export const Head: HeadFC<object, Context> = ({ pageContext, location }) => {
  const { data } = useCatalogue();
  const slug = propertySlug(location.pathname) ?? pageContext.slug;
  const property = data.find((item) => item.slug === slug);

  if (!property || !isPublished(property)) return <>
    <title>Property | Kelley Road Property Management</title>
    <meta name="robots" content="noindex, follow" />
  </>;

  /* The property's own photograph, as the share card. A listing pasted into
     a message is worth looking at; the brand card is for pages that have no
     picture of their own.

     Two sources, because the two kinds of property store pictures
     differently: one made in the CMS carries its images as URLs already,
     while a bundled one names a key that the image map turns into a built
     asset path. Both resolve at build time, so every property page gets a
     real photograph rather than the logo. */
  const photo =
    featuredImage(property)?.src || resolveProperty(property).image || undefined;

  return (
    <Seo
      title={`${property.title} | Kelley Road Property Management`}
      description={
        property.summary ||
        `${property.type} in ${property.location}, managed by Kelley Road Property Management.`
      }
      pathname={`/properties/${property.slug}/`}
      image={photo}
      type="article"
    />
  );
};
