import React, { useState } from "react";
import { Link } from "gatsby";
import {
  LuArrowRight,
  LuBath,
  LuBedDouble,
  LuCalendarCheck,
  LuExpand,
  LuMaximize,
} from "react-icons/lu";

import type {
  FloorPlanLabels,
  FloorPlanTemplate,
} from "../../templates/floor-plans/default-template";
import type { FloorPlan, FloorPlanAvailability } from "./types";

export type FloorPlansProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: FloorPlanTemplate;
  plans: FloorPlan[];
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  /** Slug of the property these plans belong to, passed into the apply flow. */
  propertySlug: string;
  /** Shown when a property has no floor-plan data at all. */
  emptyMessage?: string;
  contactHref?: string;
  applyHref?: string;
  enabled?: boolean;
  labels?: Partial<FloorPlanLabels>;
};

const number = new Intl.NumberFormat("en-US");
const pad = (n: number) => String(n).padStart(2, "0");

const AVAILABILITY_TEXT: Record<FloorPlanAvailability, string> = {
  available: "Available",
  limited: "Limited Availability",
  contact: "Contact for Availability",
  unavailable: "Not Currently Available",
};

/**
 * The interactive floor-plan selector.
 *
 * One piece of state — the selected plan id — is the single source of truth.
 * Title, description, every statistic, availability, rent, the drawing and the
 * call to action all derive from it, so they cannot fall out of sync. Selecting
 * a plan updates the whole panel, not just the picture.
 */
export default function FloorPlans({
  template,
  plans,
  heading,
  propertySlug,
  emptyMessage = "Floor plan information is available on request.",
  contactHref = "/contact",
  applyHref = "/apply",
  enabled = true,
  labels: labelOverrides,
}: FloorPlansProps) {
  const labels = { ...template.labels, ...labelOverrides };
  const [activeId, setActiveId] = useState(plans[0]?.id);

  if (!enabled) return null;

  const root = template.rootClass;

  // No plans is a real state for some properties — say so briefly rather than
  // rendering an empty section.
  if (plans.length === 0) {
    return (
      <section className={root}>
        <style>{template.css}</style>
        <div className={`${root}__inner`}>
          {heading ? <div className={`${root}__heading`}>{heading}</div> : null}
          <div className={`${root}__empty`}>
            <p>{emptyMessage}</p>
            <div className={`${root}__actions`}>
              <Link className="kr-btn kr-btn--dark" to={contactHref}>
                Contact Us
                <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
              </Link>
            </div>
          </div>
        </div>
      </section>
    );
  }

  const active = plans.find((plan) => plan.id === activeId) || plans[0];
  const canApply = active.availability === "available" || active.availability === "limited";

  const stats = [
    {
      icon: LuBedDouble,
      value: active.bedrooms === 0 ? "Studio" : pad(active.bedrooms),
      label: active.bedrooms === 1 ? labels.bedroom : labels.bedrooms,
    },
    {
      icon: LuBath,
      value: pad(active.bathrooms),
      label: active.bathrooms === 1 ? labels.bathroom : labels.bathrooms,
    },
    {
      icon: LuMaximize,
      value: number.format(active.squareFeet),
      label: labels.area,
    },
  ];

  return (
    <section className={root}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        {heading ? <div className={`${root}__heading`}>{heading}</div> : null}

        <div className={`${root}__layout`}>
          <div className={`${root}__selector`}>
            <ul className={`${root}__options`} role="tablist" aria-label={labels.selectorLabel}>
              {plans.map((plan, index) => (
                <li key={plan.id} role="presentation">
                  <button
                    type="button"
                    role="tab"
                    id={`${root}-tab-${plan.id}`}
                    className={`${root}__option`}
                    aria-selected={plan.id === active.id}
                    aria-controls={`${root}-panel-${plan.id}`}
                    tabIndex={plan.id === active.id ? 0 : -1}
                    onClick={() => setActiveId(plan.id)}
                    onKeyDown={(event) => {
                      // Arrow keys move between tabs, as tab semantics require.
                      if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
                      event.preventDefault();
                      const step = event.key === "ArrowDown" ? 1 : -1;
                      const next = plans[(index + step + plans.length) % plans.length];
                      setActiveId(next.id);
                      document.getElementById(`${root}-tab-${next.id}`)?.focus();
                    }}
                  >
                    <span className={`${root}__option-number`}>{pad(index + 1)}</span>
                    {plan.label}
                  </button>
                </li>
              ))}
            </ul>
          </div>

          <div
            className={`${root}__detail-col`}
            role="tabpanel"
            id={`${root}-panel-${active.id}`}
            aria-labelledby={`${root}-tab-${active.id}`}
          >
            {/* Keyed on the plan so the swap animation replays on change. */}
            <div className={`${root}__detail`} key={active.id}>
              <h3 className={`${root}__title`}>{active.title}</h3>
              <p className={`${root}__description`}>{active.description}</p>

              <ul className={`${root}__stats`}>
                {stats.map((stat) => {
                  const Icon = stat.icon;
                  return (
                    <li key={stat.label} className={`${root}__stat`}>
                      <span className={`${root}__stat-icon`} aria-hidden="true">
                        <Icon size={19} strokeWidth={1.4} />
                      </span>
                      <span className={`${root}__stat-value`}>{stat.value}</span>
                      <span className={`${root}__stat-label`}>{stat.label}</span>
                    </li>
                  );
                })}

                <li className={`${root}__stat`}>
                  <span className={`${root}__stat-icon`} aria-hidden="true">
                    <LuCalendarCheck size={19} strokeWidth={1.4} />
                  </span>
                  <span
                    className={`${root}__stat-value ${root}__availability${
                      canApply ? "" : ` ${root}__availability--muted`
                    }`}
                    style={{ fontSize: 15 }}
                  >
                    <span className={`${root}__availability-dot`} aria-hidden="true" />
                    {AVAILABILITY_TEXT[active.availability]}
                  </span>
                  <span className={`${root}__stat-label`}>{labels.availabilityLabel}</span>
                </li>
              </ul>

              <div className={`${root}__rent`}>
                <span className={`${root}__rent-label`}>{labels.rentLabel}</span>
                {/* Never invent a figure — say so instead. */}
                {active.rentFrom === null ? (
                  <span className={`${root}__rent-value`}>
                    <span style={{ fontSize: 18 }}>{labels.contactForPricing}</span>
                  </span>
                ) : (
                  <span className={`${root}__rent-value`}>
                    ${number.format(active.rentFrom)}
                    <span className={`${root}__rent-period`}>{labels.rentPeriod}</span>
                  </span>
                )}
              </div>

              <div className={`${root}__actions`}>
                <Link
                  className="kr-btn kr-btn--gold"
                  to={
                    canApply
                      ? `${applyHref}?property=${propertySlug}&floorPlan=${active.id}`
                      : `${contactHref}?property=${propertySlug}&floorPlan=${active.id}`
                  }
                >
                  {canApply ? "Apply for This Unit" : "Ask About This Floor Plan"}
                  <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
                </Link>
              </div>
            </div>
          </div>

          {/* A unit without a drawing keeps its name, size, availability and
              price — a missing picture is not a missing unit. The frame and the
              expand control are omitted rather than filled with a placeholder,
              and never with another unit's plan, which would be a drawing of
              somewhere the visitor is not looking at. */}
          {active.image ? (
            <div className={`${root}__viewer`}>
              <div className={`${root}__block`} aria-hidden="true" />
              <div className={`${root}__frame`}>
                {/* Both keyed on the plan: the wipe and the crossfade replay together. */}
                <img
                  className={`${root}__plan`}
                  key={`plan-${active.id}`}
                  src={active.image.src}
                  alt={active.image.alt}
                  loading="lazy"
                  decoding="async"
                />
                <span
                  className={`${root}__wipe`}
                  key={`wipe-${active.id}`}
                  aria-hidden="true"
                />
                <button
                  type="button"
                  className={`${root}__expand`}
                  onClick={() =>
                    active.image &&
                    window.open(active.image.src, "_blank", "noopener")
                  }
                >
                  <LuExpand size={13} strokeWidth={1.75} aria-hidden="true" />
                  {labels.expand}
                </button>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </section>
  );
}
