// Styling for the property overview.
//
// The counterpart to the floor plans above it: 011 answers "what unit can I
// choose", this answers "what is this property and community like". Nothing
// unit-specific is repeated here.
//
// Composition is asymmetric on purpose — 45/55, content left, a large
// photograph right with a smaller supporting image overlapping its lower-left
// corner. The supporting image sits inside a reserved overhang so it can never
// be clipped by the section.

import brand from "../brand";

export type OverviewTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
};

const color = {
  background: brand.colors.background,
  /** Soft block behind part of the imagery. */
  block: brand.colors.backgroundAlt,

  lead: brand.colors.primary,
  body: brand.colors.textMuted,

  detailLabel: brand.colors.accent,
  detailValue: brand.colors.text,
  divider: brand.colors.border,

  amenityIcon: brand.colors.accent,
  amenityText: brand.colors.text,

  moreLink: brand.colors.primary,
  moreLinkHover: brand.colors.accent,

  mediaPlaceholder: brand.colors.border,
  insetFrame: brand.colors.background,
  insetShadow: "0 18px 44px rgba(31, 35, 40, .16)",
  rule: brand.colors.accent,

  focus: brand.colors.accent,
};

const layout = {
  maxWidth: 1280,
  contentColumn: "45fr",
  visualColumn: "55fr",
  mainAspect: "4 / 3",
  insetAspect: "4 / 3",
  insetWidth: "44%",
  visualPadBottom: 62,
  radius: 2,
  mainZoom: 1.02,
  insetLift: -4,
  stackBelow: 960,
};

const spacing = {
  sectionTop: 100,
  sectionBottom: 104,
  sectionTopCompact: 68,
  sectionBottomCompact: 72,
  gutter: 40,
  gutterCompact: 20,
  columnGap: 66,
  columnGapCompact: 44,
  leadGap: 6,
  bodyGap: 20,
  blockGap: 40,
  detailPaddingY: 16,
  amenityGapY: 14,
  ctaGap: 36,
};

const typography = {
  leadFamily: brand.typography.body,
  leadSize: "clamp(16px, 1.3vw, 18px)",
  leadWeight: brand.typography.weight.medium,
  leadLeading: 1.6,

  bodyFamily: brand.typography.body,
  bodySize: 14.5,
  bodyWeight: brand.typography.weight.regular,
  bodyLeading: 1.75,

  sublabelFamily: brand.typography.body,
  sublabelSize: 10.5,
  sublabelWeight: brand.typography.weight.semibold,
  sublabelTracking: "0.18em",

  detailValueFamily: brand.typography.body,
  detailValueSize: 14.5,
  detailValueWeight: brand.typography.weight.medium,

  amenityFamily: brand.typography.body,
  amenitySize: 14,
  amenityWeight: brand.typography.weight.regular,

  moreFamily: brand.typography.body,
  moreSize: 11,
  moreWeight: brand.typography.weight.semibold,
  moreTracking: "0.14em",
};

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-ov {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-ov__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.contentColumn} ${layout.visualColumn};
  align-items: start;
  gap: ${spacing.columnGap}px;
}

/* ── copy ─────────────────────────────────────────────── */
.kr-ov__lead {
  margin: ${spacing.leadGap}px 0 ${spacing.bodyGap}px;
  color: ${color.lead};
  font-family: ${typography.leadFamily};
  font-size: ${typography.leadSize};
  font-weight: ${typography.leadWeight};
  line-height: ${typography.leadLeading};
}
.kr-ov__body p {
  margin: 0 0 ${spacing.bodyGap}px;
  color: ${color.body};
  font-family: ${typography.bodyFamily};
  font-size: ${typography.bodySize}px;
  font-weight: ${typography.bodyWeight};
  line-height: ${typography.bodyLeading};
}
.kr-ov__body p:last-child { margin-bottom: 0; }

.kr-ov__more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  border: 0;
  padding: 0;
  background: none;
  color: ${color.moreLink};
  font-family: ${typography.moreFamily};
  font-size: ${typography.moreSize}px;
  font-weight: ${typography.moreWeight};
  letter-spacing: ${typography.moreTracking};
  text-transform: uppercase;
  cursor: pointer;
  transition: color ${'.24s'} ${ease};
}
.kr-ov__more:hover { color: ${color.moreLinkHover}; }
.kr-ov__more:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── subsection heads ─────────────────────────────────── */
.kr-ov__sublabel {
  margin: ${spacing.blockGap}px 0 6px;
  color: ${color.detailLabel};
  font-family: ${typography.sublabelFamily};
  font-size: ${typography.sublabelSize}px;
  font-weight: ${typography.sublabelWeight};
  letter-spacing: ${typography.sublabelTracking};
  text-transform: uppercase;
}

/* ── property facts ───────────────────────────────────────
   Two columns of label-over-value with hairlines, not six floating cards. */
.kr-ov__details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 28px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-ov__detail {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: ${spacing.detailPaddingY}px 0;
  border-bottom: 1px solid ${color.divider};
}
.kr-ov__detail-icon { color: ${color.detailLabel}; display: inline-flex; margin-top: 3px; flex-shrink: 0; }
.kr-ov__detail-label {
  display: block;
  margin-bottom: 3px;
  color: ${color.detailLabel};
  font-family: ${typography.sublabelFamily};
  font-size: ${typography.sublabelSize}px;
  font-weight: ${typography.sublabelWeight};
  letter-spacing: ${typography.sublabelTracking};
  text-transform: uppercase;
}
.kr-ov__detail-value {
  display: block;
  color: ${color.detailValue};
  font-family: ${typography.detailValueFamily};
  font-size: ${typography.detailValueSize}px;
  font-weight: ${typography.detailValueWeight};
}

/* ── amenities ────────────────────────────────────────── */
.kr-ov__amenities {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: ${spacing.amenityGapY}px 24px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-ov__amenity {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: ${color.amenityText};
  font-family: ${typography.amenityFamily};
  font-size: ${typography.amenitySize}px;
  font-weight: ${typography.amenityWeight};
}
.kr-ov__amenity-icon { color: ${color.amenityIcon}; display: inline-flex; margin-top: 2px; flex-shrink: 0; }

.kr-ov__actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: ${spacing.ctaGap}px; }

/* ── imagery ──────────────────────────────────────────────
   The bottom padding reserves the overhang so the inset can never be clipped. */
.kr-ov__visual {
  position: relative;
  isolation: isolate;
  padding-bottom: ${layout.visualPadBottom}px;
}
.kr-ov__block {
  position: absolute;
  right: -26px;
  top: -26px;
  z-index: 0;
  width: 46%;
  height: 40%;
  background: ${color.block};
  pointer-events: none;
}
.kr-ov__main {
  position: relative;
  z-index: 1;
  aspect-ratio: ${layout.mainAspect};
  border-radius: ${layout.radius}px;
  background: ${color.mediaPlaceholder};
  overflow: hidden;
  clip-path: inset(0 0 0 100%);
  transition: clip-path 780ms ${ease} 100ms;
}
.kr-ov--in .kr-ov__main { clip-path: inset(0 0 0 0); }
.kr-ov__main-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 560ms ${ease};
}
.kr-ov__visual:hover .kr-ov__main-image { transform: scale(${layout.mainZoom}); }

.kr-ov__rule {
  position: absolute;
  left: -14px;
  top: 14%;
  z-index: 2;
  width: 2px;
  height: 32%;
  background: ${color.rule};
  transform: scaleY(0);
  transform-origin: top center;
  transition: transform 780ms ${ease} 100ms;
}
.kr-ov--in .kr-ov__rule { transform: scaleY(1); }

.kr-ov__inset {
  position: absolute;
  left: -5%;
  bottom: 0;
  z-index: 2;
  width: ${layout.insetWidth};
  padding: 9px;
  background: ${color.insetFrame};
  border-radius: ${layout.radius}px;
  box-shadow: ${color.insetShadow};
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 480ms ${ease} 640ms, transform 480ms ${ease} 640ms;
}
.kr-ov--in .kr-ov__inset { opacity: 1; transform: translateY(0); }
.kr-ov--in .kr-ov__visual:hover .kr-ov__inset {
  transform: translateY(${layout.insetLift}px);
  transition-delay: 0ms;
  transition-duration: 560ms;
}
.kr-ov__inset-figure {
  display: block;
  aspect-ratio: ${layout.insetAspect};
  border-radius: 1px;
  overflow: hidden;
  background: ${color.mediaPlaceholder};
}
.kr-ov__inset-image { width: 100%; height: 100%; object-fit: cover; display: block; }

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.stackBelow}px) {
  .kr-ov {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-ov__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
    padding: 0 ${spacing.gutterCompact}px;
  }
  .kr-ov__visual { order: -1; max-width: 560px; }
  .kr-ov__rule { display: none; }
  .kr-ov__inset { left: auto; right: 4%; width: 42%; }
}

@media (max-width: 460px) {
  /* Overlap gets cramped here — the inset drops below instead. */
  .kr-ov__visual { padding-bottom: 0; }
  .kr-ov__inset {
    position: static;
    width: 100%;
    margin-top: 14px;
    padding: 0;
    box-shadow: none;
  }
  .kr-ov__details,
  .kr-ov__amenities { grid-template-columns: minmax(0, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  .kr-ov__main { clip-path: inset(0 0 0 0); transition: none; }
  .kr-ov__rule { transform: scaleY(1); transition: none; }
  .kr-ov__inset { opacity: 1; transform: none; transition: none; }
  .kr-ov__main-image { transition: none; }
  .kr-ov__visual:hover .kr-ov__main-image { transform: none; }
}
`;

const noscriptCss = `
.kr-ov__main { clip-path: inset(0 0 0 0); }
.kr-ov__rule { transform: scaleY(1); }
.kr-ov__inset { opacity: 1; transform: none; }
`;

const template: OverviewTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-ov",
};

export default template;
