import React, { useCallback, useEffect, useRef } from "react";
import { LuArrowLeft, LuArrowRight, LuX } from "react-icons/lu";

import type { GalleryLabels } from "../../templates/gallery/default-template";
import type { GalleryImage } from "./types";

type Props = {
  images: GalleryImage[];
  /** Index of the open image, or null when closed. */
  index: number | null;
  labels: GalleryLabels;
  onClose: () => void;
  onNavigate: (next: number) => void;
};

/**
 * Full-screen photograph viewer.
 *
 * Handles the things a lightbox has to get right and usually does not: focus
 * moves in on open and returns to whatever opened it on close, Escape and the
 * arrow keys work, focus is trapped inside while open, and the page behind
 * cannot scroll.
 */
export default function Lightbox({
  images,
  index,
  labels,
  onClose,
  onNavigate,
}: Props) {
  const open = index !== null;
  const panelRef = useRef<HTMLDivElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const returnFocusRef = useRef<HTMLElement | null>(null);

  const go = useCallback(
    (step: number) => {
      if (index === null || images.length === 0) return;
      onNavigate((index + step + images.length) % images.length);
    },
    [index, images.length, onNavigate]
  );

  useEffect(() => {
    if (!open) return;

    returnFocusRef.current = document.activeElement as HTMLElement | null;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
        return;
      }
      if (event.key === "ArrowRight") {
        event.preventDefault();
        go(1);
        return;
      }
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        go(-1);
        return;
      }
      if (event.key !== "Tab") return;

      // Trap: without this, tabbing walks into the page behind the overlay.
      const focusable = panelRef.current?.querySelectorAll<HTMLElement>(
        "button, [href], input, select, textarea, [tabindex]:not([tabindex='-1'])"
      );
      if (!focusable || focusable.length === 0) return;

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", onKeyDown);
    closeRef.current?.focus();

    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", onKeyDown);
      returnFocusRef.current?.focus();
    };
  }, [open, go, onClose]);

  const image = index === null ? null : images[index];

  return (
    <div
      ref={panelRef}
      className={`kr-lightbox${open ? " kr-lightbox--open" : ""}`}
      role="dialog"
      aria-modal="true"
      aria-label={labels.region}
      aria-hidden={!open}
      {...(open ? {} : { inert: "" })}
    >
      <div className="kr-lightbox__bar">
        <div className="kr-lightbox__meta">
          {image?.category ? (
            <span className="kr-lightbox__category">{image.category}</span>
          ) : null}
          <span className="kr-lightbox__name">{image?.label}</span>
        </div>

        <div className="kr-lightbox__nav">
          <span className="kr-lightbox__count">
            {index === null ? "" : `${index + 1} / ${images.length}`}
          </span>
          {images.length > 1 ? (
            <>
              <button
                type="button"
                className="kr-lightbox__control"
                aria-label={labels.previous}
                onClick={() => go(-1)}
              >
                <LuArrowLeft size={17} strokeWidth={1.6} />
              </button>
              <button
                type="button"
                className="kr-lightbox__control"
                aria-label={labels.next}
                onClick={() => go(1)}
              >
                <LuArrowRight size={17} strokeWidth={1.6} />
              </button>
            </>
          ) : null}
          <button
            ref={closeRef}
            type="button"
            className="kr-lightbox__control"
            aria-label={labels.close}
            onClick={onClose}
          >
            <LuX size={17} strokeWidth={1.6} />
          </button>
        </div>
      </div>

      <div className="kr-lightbox__stage">
        {image ? (
          <img className="kr-lightbox__image" src={image.src} alt={image.alt} />
        ) : null}
      </div>
    </div>
  );
}
