import React, { useEffect, useState } from "react";
import { Link } from "gatsby";
import { LuArrowRight, LuMapPin } from "react-icons/lu";

import type {
  PropertyHeroLabels,
  PropertyHeroTemplate,
} from "../../templates/property-hero/default-template";
import type { Property } from "../property/types";
import {
  bedroomSummary,
  isAvailable,
  photoCount,
  startingPrice,
} from "../property/derive";

export type PropertyMiniHeroProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: PropertyHeroTemplate;
  /** Everything shown here is derived from this one record. */
  property: Property & {
    photoCount?: number;
    rentFrom?: number | null;
  };
  /** Anchor the photo-count control scrolls to. */
  galleryHref?: string;
  labels?: Partial<PropertyHeroLabels>;
};

const number = new Intl.NumberFormat("en-US");

/**
 * The property page's opening statement: which property is this.
 *
 * Deliberately restrained — type, size and starting rent only. Bathrooms,
 * square footage, amenities and lease terms belong further down the page, not
 * competing with the property's name.
 *
 * Unlike the homepage sections this reveals on mount rather than on scroll: it
 * sits at the top of the page, so waiting for an intersection would mean the
 * visitor watches a blank hero for a frame.
 */
export default function PropertyMiniHero({
  template,
  property,
  galleryHref = "#gallery",
  labels: labelOverrides,
}: PropertyMiniHeroProps) {
  const labels = { ...template.labels, ...labelOverrides };
  const [entered, setEntered] = useState(false);

  useEffect(() => {
    // A frame's delay so the browser paints the pre-reveal state first;
    // without it the transition has nothing to animate from.
    const id = requestAnimationFrame(() => setEntered(true));
    return () => cancelAnimationFrame(id);
  }, []);

  const root = template.rootClass;

  /* Derived rather than read, so the hero, the card and the search filters
     cannot disagree, and a building offering a studio through a two-bed says
     so instead of printing one of its unit's numbers. See modules/property/
     derive.ts, which owns every rule of this kind. */
  const beds = bedroomSummary(property);
  const price = startingPrice(property);
  const photos = photoCount(property) || property.photoCount || 0;

  return (
    <section className={`${root}${entered ? ` ${root}--in` : ""}`}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__media`}>
        <img
          className={`${root}__image`}
          src={property.image}
          srcSet={property.imageSrcSet}
          sizes={property.imageSrcSet ? "(max-width: 900px) 100vw, 58vw" : undefined}
          alt={property.imageAlt}
          /* Largest paint on the page, and above the fold. */
          loading="eager"
          decoding="sync"
        />
        <span className={`${root}__fade`} aria-hidden="true" />
        <span className={`${root}__sweep`} aria-hidden="true" />
        <span className={`${root}__corner`} aria-hidden="true" />

        {property.availability ? (
          <span className={`${root}__status`}>
            <span className={`${root}__status-dot`} aria-hidden="true" />
            {property.availability}
          </span>
        ) : null}

        {photos ? (
          <a className={`${root}__photos`} href={galleryHref}>
            {labels.viewPhotos.replace("{n}", String(photos))}
            <span className={`${root}__photos-arrow`} aria-hidden="true">
              <LuArrowRight size={13} strokeWidth={1.75} />
            </span>
          </a>
        ) : null}
      </div>

      <div className={`${root}__inner`}>
        <div className={`${root}__content`}>
          {/* Only when something is genuinely available. It used to render
              for any non-empty availability text, so a property reading
              "Contact for Availability" was still announced as available. */}
          {isAvailable(property) ? (
            <p className={`${root}__eyebrow`}>Available Property</p>
          ) : null}

          <h1 className={`${root}__title`}>{property.title}</h1>

          <p className={`${root}__location`}>
            <span className={`${root}__location-icon`} aria-hidden="true">
              <LuMapPin size={16} strokeWidth={1.5} />
            </span>
            {property.location}
          </p>

          <ul className={`${root}__meta`}>
            <li>{property.type}</li>
            {/* Omitted when it carries nothing, and when it would only repeat
                the type: a studio listing was printing "Studio · Studio". */}
            {beds && beds.toLowerCase() !== property.type.toLowerCase() ? (
              <li>{beds}</li>
            ) : null}
            {/* Says "Contact for pricing" rather than dropping the line, which
                is what the floor-plan panel has always done for the same
                state — the two surfaces now agree. */}
            <li className={`${root}__meta-rent`}>
              {price.kind === "monthly"
                ? `From $${number.format(price.amount)} / month`
                : "Contact for pricing"}
            </li>
          </ul>

          <nav className={`${root}__crumbs`} aria-label={labels.breadcrumbLabel}>
            <ol>
              <li>
                <Link to="/">{labels.home}</Link>
              </li>
              <li>
                <Link to="/properties">{labels.properties}</Link>
              </li>
              <li>
                <span aria-current="page">{property.title}</span>
              </li>
            </ol>
          </nav>
        </div>
      </div>
    </section>
  );
}
