/** Never render more tabs than the strip can hold on one row. */
const MAX_PLANS = 4;

export type FloorPlansXProps = {
  slug: string;
  /**
   * This property's own unit types.
   *
   * When a record carries them they are used as-is. Everything below is the
   * seed for the twelve bundled listings, which have none of their own yet.
   */
  plans?: FloorPlan[];
};

/**
 * The property floor plans, configured.
 *
 * A unit owns its own bedrooms, size, availability and price. That matters
 * because those are the most property-specific and most time-sensitive facts
 * on the page, and until now they were global: five listings shared one
 * "1 Bed + Den" object, so none of them could differ on rent or availability
 * even in principle. A record's own `floorPlans` replaces the shared library
 * entirely; the library remains only as the seed.
 */
export default function FloorPlansX({ slug, plans: own }: FloorPlansXProps) {
  const seeded = (PLANS_BY_PROPERTY[slug] || [])
    .map((id) => PLAN_LIBRARY[id])
    .filter(Boolean);

  const plans = (own?.length ? own : seeded).slice(0, MAX_PLANS);

  return (
    <FloorPlans
      template={template}
      enabled={floorPlansEnabled}
      plans={plans}
      propertySlug={slug}
      heading={
        <SectionTitle
          backgroundText="Floor Plans"
          title="Explore Floor Plans"
          description="Compare available layouts and the space, features and details that matter most to you."
          align="left"
        />
      }
    />
  );
}
