// Styling for the property mini hero.
//
// Compact by design: this is an interior page announcing which property you
// are looking at, not a second homepage hero.
//
// The photograph is absolutely positioned to the right and bleeds off the
// viewport edge, so it reads as part of the composition rather than as a
// rectangle placed beside the text. Its left edge dissolves into the section
// background over a narrow band — the right side stays fully crisp.
//
// The wipe is the signature motion: a gold layer sweeps left-to-right just
// ahead of the photograph, then the image settles from 1.03 to 1.00. Both
// animate on the compositor.

import template1 from "./template-1";

export type PropertyHeroLabels = {
  breadcrumbLabel: string;
  home: string;
  properties: string;
  /** `{n}` replaced by the photo count. */
  viewPhotos: string;
};

export type PropertyHeroTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
  labels: PropertyHeroLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: PropertyHeroLabels = {
  breadcrumbLabel: "Breadcrumb",
  home: "Home",
  properties: "Properties",
  viewPhotos: "View {n} Photos",
};

const css = `
.kr-mhero {
  position: relative;
  min-height: ${layout.height}px;
  display: flex;
  align-items: center;
  background: ${color.background};
  overflow: hidden;
  isolation: isolate;
}

/* ── photograph ───────────────────────────────────────── */
.kr-mhero__media {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 0;
  width: ${layout.mediaWidth};
  overflow: hidden;
  /* Signature motion: reveals left-to-right. */
  clip-path: inset(0 0 0 100%);
  transition: clip-path ${timing.reveal}ms ${ease} ${timing.revealDelay}ms;
}
.kr-mhero--in .kr-mhero__media { clip-path: inset(0 0 0 0); }

.kr-mhero__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform: scale(${layout.settleFrom});
  transition: transform ${timing.settle}ms ${ease} ${timing.revealDelay}ms;
}
.kr-mhero--in .kr-mhero__image { transform: scale(1); }

/* Gold layer running just ahead of the photograph as it arrives. */
.kr-mhero__sweep {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: ${color.revealSweep};
  transform-origin: left center;
  transform: scaleX(1);
  pointer-events: none;
}
.kr-mhero--in .kr-mhero__sweep {
  transform: scaleX(0);
  transform-origin: right center;
  transition: transform ${timing.reveal}ms ${ease} ${timing.revealDelay}ms;
}

.kr-mhero__fade {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: ${color.fade};
  pointer-events: none;
}

/* Small architectural corner, lower left of the image. */
.kr-mhero__corner {
  position: absolute;
  left: ${layout.cornerInset}px;
  bottom: ${layout.cornerInset}px;
  z-index: 3;
  width: ${layout.cornerSize}px;
  height: ${layout.cornerSize}px;
  border-left: ${layout.cornerThickness}px solid ${color.corner};
  border-bottom: ${layout.cornerThickness}px solid ${color.corner};
  opacity: 0;
  transition: opacity ${timing.badge}ms ${ease} ${timing.badgeDelay}ms;
  pointer-events: none;
}
.kr-mhero--in .kr-mhero__corner { opacity: 1; }

/* ── badges over the image ────────────────────────────── */
.kr-mhero__status,
.kr-mhero__photos {
  position: absolute;
  z-index: 4;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: ${layout.radius}px;
  font-family: ${typography.badgeFamily};
  font-size: ${typography.badgeSize}px;
  font-weight: ${typography.badgeWeight};
  letter-spacing: ${typography.badgeTracking};
  text-transform: uppercase;
  line-height: 1;
  white-space: nowrap;
  opacity: 0;
  transform: translateY(8px);
  transition:
    opacity ${timing.badge}ms ${ease} ${timing.badgeDelay}ms,
    transform ${timing.badge}ms ${ease} ${timing.badgeDelay}ms,
    background-color ${timing.hover}ms ${ease},
    color ${timing.hover}ms ${ease};
}
.kr-mhero--in .kr-mhero__status,
.kr-mhero--in .kr-mhero__photos { opacity: 1; transform: translateY(0); }

.kr-mhero__status {
  top: ${spacing.badgeInset}px;
  right: ${spacing.badgeInset}px;
  background: ${color.statusBackground};
  color: ${color.statusText};
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}
.kr-mhero__status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: ${color.statusDot};
}

.kr-mhero__photos {
  right: ${spacing.badgeInset}px;
  bottom: ${spacing.badgeInset}px;
  background: ${color.photosBackground};
  color: ${color.photosText};
  text-decoration: none;
  cursor: pointer;
  border: 0;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}
.kr-mhero__photos:hover {
  background: ${color.photosHoverBackground};
  color: ${color.photosHoverText};
}
.kr-mhero__photos:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-mhero__photos-arrow { transition: transform ${timing.hover}ms ${ease}; }
.kr-mhero__photos:hover .kr-mhero__photos-arrow { transform: translateX(3px); }

/* ── content ──────────────────────────────────────────── */
.kr-mhero__inner {
  position: relative;
  z-index: 5;
  width: 100%;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-mhero__content { max-width: 44%; }

.kr-mhero__eyebrow,
.kr-mhero__title,
.kr-mhero__location,
.kr-mhero__meta,
.kr-mhero__crumbs {
  opacity: 0;
  transform: translateY(14px);
  transition:
    opacity var(--kr-mhero-duration) ${ease} var(--kr-mhero-delay),
    transform var(--kr-mhero-duration) ${ease} var(--kr-mhero-delay);
}
.kr-mhero__eyebrow  { --kr-mhero-duration: ${timing.eyebrow}ms;  --kr-mhero-delay: ${timing.eyebrowDelay}ms; }
.kr-mhero__title    { --kr-mhero-duration: ${timing.title}ms;    --kr-mhero-delay: ${timing.titleDelay}ms; }
.kr-mhero__location { --kr-mhero-duration: ${timing.location}ms; --kr-mhero-delay: ${timing.locationDelay}ms; }
.kr-mhero__meta     { --kr-mhero-duration: ${timing.meta}ms;     --kr-mhero-delay: ${timing.metaDelay}ms; }
.kr-mhero__crumbs   { --kr-mhero-duration: ${timing.crumbs}ms;   --kr-mhero-delay: ${timing.crumbsDelay}ms; }

.kr-mhero--in .kr-mhero__eyebrow,
.kr-mhero--in .kr-mhero__title,
.kr-mhero--in .kr-mhero__location,
.kr-mhero--in .kr-mhero__meta,
.kr-mhero--in .kr-mhero__crumbs { opacity: 1; transform: none; }

.kr-mhero__eyebrow {
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;
}
.kr-mhero__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
}
.kr-mhero__location {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 ${spacing.locationGap}px;
  color: ${color.locationText};
  font-family: ${typography.locationFamily};
  font-size: ${typography.locationSize}px;
  font-weight: ${typography.locationWeight};
}
.kr-mhero__location-icon { display: inline-flex; color: ${color.locationIcon}; flex-shrink: 0; }

/* Restrained: type, size and rent only. Everything else waits for KRP-012. */
.kr-mhero__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: ${spacing.metaItemGap}px;
  margin: 0 0 ${spacing.metaGap}px;
  padding: 0;
  list-style: none;
}
.kr-mhero__meta li {
  display: inline-flex;
  align-items: center;
  gap: ${spacing.metaItemGap}px;
  color: ${color.metaText};
  font-family: ${typography.metaFamily};
  font-size: ${typography.metaSize}px;
  font-weight: ${typography.metaWeight};
  letter-spacing: ${typography.metaTracking};
  text-transform: uppercase;
}
.kr-mhero__meta li + li::before {
  content: "";
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: ${color.metaDot};
}
.kr-mhero__meta-rent { color: ${color.metaRent}; }

/* ── breadcrumb ───────────────────────────────────────── */
.kr-mhero__crumbs ol {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: ${spacing.crumbGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-mhero__crumbs li {
  display: inline-flex;
  align-items: center;
  gap: ${spacing.crumbGap}px;
  font-family: ${typography.crumbFamily};
  font-size: ${typography.crumbSize}px;
  font-weight: ${typography.crumbWeight};
}
.kr-mhero__crumbs li + li::before {
  content: "/";
  color: ${color.crumbSeparator};
}
.kr-mhero__crumbs a {
  color: ${color.crumbLink};
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
.kr-mhero__crumbs a:hover { color: ${color.crumbLinkHover}; }
.kr-mhero__crumbs a:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-mhero__crumbs [aria-current="page"] { color: ${color.crumbCurrent}; }

/* ── responsive ───────────────────────────────────────────
   Recomposed, not squeezed: the photograph becomes a full-width band above
   the content rather than a shrinking column beside it. */
@media (max-width: 1180px) {
  .kr-mhero__content { max-width: 50%; }
}
@media (max-width: 1024px) {
  .kr-mhero { min-height: ${layout.heightTablet}px; }
  .kr-mhero__media { width: ${layout.mediaWidthTablet}; }
  .kr-mhero__content { max-width: 52%; }
}

@media (max-width: ${layout.stackBelow}px) {
  .kr-mhero {
    display: block;
    min-height: 0;
    padding-bottom: 44px;
  }
  .kr-mhero__media {
    position: relative;
    width: 100%;
    aspect-ratio: ${layout.mobileAspect};
  }
  .kr-mhero__fade { display: none; }
  .kr-mhero__inner { padding: ${spacing.mobileContentTop}px ${spacing.gutterCompact}px 0; }
  .kr-mhero__content { max-width: none; }
  .kr-mhero__corner { left: 14px; bottom: 14px; width: 40px; height: 40px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-mhero__media { clip-path: inset(0 0 0 0); transition: none; }
  .kr-mhero__image { transform: none; transition: none; }
  .kr-mhero__sweep { display: none; }
  .kr-mhero__corner,
  .kr-mhero__status,
  .kr-mhero__photos,
  .kr-mhero__eyebrow,
  .kr-mhero__title,
  .kr-mhero__location,
  .kr-mhero__meta,
  .kr-mhero__crumbs {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
`;

const noscriptCss = `
.kr-mhero__media { clip-path: inset(0 0 0 0); }
.kr-mhero__image { transform: none; }
.kr-mhero__sweep { display: none; }
.kr-mhero__corner,
.kr-mhero__status,
.kr-mhero__photos,
.kr-mhero__eyebrow,
.kr-mhero__title,
.kr-mhero__location,
.kr-mhero__meta,
.kr-mhero__crumbs { opacity: 1; transform: none; }
`;

const template: PropertyHeroTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-mhero",
  timing,
  labels,
};

export default template;
