import React from "react";

import cardTemplate from "../../config/property-card--template";
import carouselTemplate from "../../config/property-carousel--template";
import { applySimilarOverrides, publishedOnly } from "../../modules/property/derive";
import findSimilarProperties from "../../modules/property/findSimilar";
import PropertyCarousel from "../../modules/property/PropertyCarousel";
import type { PropertyRecord } from "../../modules/property/types";
import similarEnabled from "../../toggles/similar-properties";
import SectionTitle from "../section-title/section-title";
import { useCatalogue } from "./useCatalogue";
import { resolveProperties } from "./property-images";

export type SimilarPropertiesProps = {
  /** The property being viewed. Always excluded from its own suggestions. */
  current: PropertyRecord;
};

/**
 * Similar Properties.
 *
 * This is MTC-KRP-005 with a different dataset and heading — the same
 * PropertyCard inside the same PropertyCarousel. Nothing about the card is
 * duplicated here, which is the whole point: change the card once and every
 * surface that shows a property changes with it.
 */
/** Matches the carousel's own limit. */
const MAX_SIMILAR = 6;

export default function SimilarProperties({ current }: SimilarPropertiesProps) {
  const { data: properties } = useCatalogue();
  /* Scored automatically, then adjusted by whatever the author pinned or
     excluded. Both are stored as slugs on the record rather than as copies of
     the properties, so pinning a listing cannot leave a stale snapshot of its
     rent behind. With no adjustments this is exactly the previous behaviour. */
  /* Drafts are never suggested, and cannot be rescued by pinning one — the
     pool is filtered before either the scoring or the manual overrides see
     it, so there is no path by which an unfinished listing reaches a
     visitor. */
  const live = publishedOnly(properties);

  const similar = applySimilarOverrides(
    findSimilarProperties(current, live),
    live,
    current.similar,
    MAX_SIMILAR
  );

  // One property in the catalogue means nothing to suggest. Render nothing
  // rather than an empty section.
  if (similar.length === 0) return null;

  return (
    <PropertyCarousel
      template={carouselTemplate}
      cardTemplate={cardTemplate}
      enabled={similarEnabled}
      alt
      properties={resolveProperties(similar)}
      heading={
        <SectionTitle
          backgroundText="Discover"
          title="Similar Properties"
          description="Explore other Kelley Road properties that may be a good fit for you."
          align="left"
        />
      }
      labels={{ region: "Similar properties carousel" }}
    />
  );
}
