// Styling for the property gallery.
//
// Centred active slide with its neighbours peeking either side, following the
// reference. Two decisions worth stating:
//
// 1. Neighbours are dimmed, not blurred. A blur says "this is unavailable";
//    reduced opacity says "this is next", which is what a gallery means.
//
// 2. The label hangs below the active photograph's lower-left corner rather
//    than sitting on top of it. Nate's requirement is that visitors always know
//    which room they are looking at — a label over the image competes with the
//    photograph, one attached beneath it never does.

import template1 from "./template-1";

export type GalleryLabels = {
  region: string;
  previous: string;
  next: string;
  expand: string;
  close: string;
  /** `{n}` and `{total}` are replaced. */
  counter: string;
  allFilter: string;
};

export type GalleryTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
  labels: GalleryLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: GalleryLabels = {
  region: "Property gallery",
  previous: "Previous photograph",
  next: "Next photograph",
  expand: "View large",
  close: "Close gallery viewer",
  counter: "Photograph {n} of {total}",
  allFilter: "All",
};

const css = `
.kr-gal {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-gal__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-gal__heading { margin-bottom: ${spacing.headingGap}px; }

/* ── category filters ─────────────────────────────────── */
.kr-gal__filters {
  display: flex;
  flex-wrap: wrap;
  gap: ${spacing.filterGap}px;
  margin-bottom: ${spacing.filterRowGap}px;
  padding: 0;
  list-style: none;
}
.kr-gal__filter {
  position: relative;
  padding: 0 0 8px;
  border: 0;
  background: none;
  color: ${color.filterText};
  font-family: ${typography.filterFamily};
  font-size: ${typography.filterSize}px;
  font-weight: ${typography.filterWeight};
  letter-spacing: ${typography.filterTracking};
  text-transform: uppercase;
  cursor: pointer;
  transition: color ${timing.hover}ms ${ease};
}
.kr-gal__filter::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: ${color.filterRule};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform ${timing.hover}ms ${ease};
}
.kr-gal__filter:hover { color: ${color.filterActive}; }
.kr-gal__filter--active { color: ${color.filterActive}; }
.kr-gal__filter--active::after { transform: scaleX(1); }
.kr-gal__filter:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── stage ────────────────────────────────────────────────
   The swiper overflows its container so neighbours reach the screen edge;
   the section clips them. */
.kr-gal__swiper { overflow: visible; }
.kr-gal__swiper .swiper-slide {
  width: ${layout.activeWidth};
  opacity: ${layout.sideOpacity};
  transform: scale(${layout.sideScale});
  transition:
    opacity ${timing.slide}ms ${ease},
    transform ${timing.slide}ms ${ease};
}
.kr-gal__swiper .swiper-slide-active { opacity: 1; transform: scale(1); }
.kr-gal__swiper { cursor: grab; }
.kr-gal__swiper:active { cursor: grabbing; }

.kr-gal__frame {
  position: relative;
  aspect-ratio: ${layout.aspect};
  border-radius: ${layout.radius}px;
  background: ${color.mediaPlaceholder};
  overflow: hidden;
}
.kr-gal__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform ${timing.hover}ms ${ease};
}
.swiper-slide-active .kr-gal__frame:hover .kr-gal__image {
  transform: scale(${layout.imageZoom});
}

/* Expand control — the image is never mysteriously clickable. */
.kr-gal__expand {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 13px;
  border: 0;
  border-radius: ${layout.radius}px;
  background: ${color.expandBackground};
  color: ${color.expandText};
  font-family: ${typography.expandFamily};
  font-size: ${typography.expandSize}px;
  font-weight: ${typography.expandWeight};
  letter-spacing: ${typography.expandTracking};
  text-transform: uppercase;
  cursor: pointer;
  opacity: 0;
  transition:
    opacity ${timing.hover}ms ${ease},
    background-color ${timing.hover}ms ${ease},
    color ${timing.hover}ms ${ease};
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}
.swiper-slide-active .kr-gal__expand { opacity: 1; }
.kr-gal__expand:hover {
  background: ${color.expandHoverBackground};
  color: ${color.expandHoverText};
}
.kr-gal__expand:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── label, hanging below the active photograph ───────── */
.kr-gal__label {
  position: absolute;
  left: ${spacing.labelOffsetX}px;
  bottom: 0;
  z-index: 3;
  transform: translateY(50%);
  padding: ${spacing.labelPaddingY}px ${spacing.labelPaddingX}px;
  background: ${color.labelBackground};
  border: 1px solid ${color.labelBorder};
  border-radius: ${layout.radius}px;
  box-shadow: ${color.labelShadow};
  opacity: 0;
  transition: opacity ${timing.label}ms ${ease};
  pointer-events: none;
}
.swiper-slide-active .kr-gal__label { opacity: 1; }

.kr-gal__label-rule {
  display: block;
  width: ${layout.labelRuleWidth}px;
  height: 2px;
  margin-bottom: 10px;
  background: ${color.labelRule};
}
.kr-gal__category {
  display: block;
  margin-bottom: 5px;
  color: ${color.category};
  font-family: ${typography.categoryFamily};
  font-size: ${typography.categorySize}px;
  font-weight: ${typography.categoryWeight};
  letter-spacing: ${typography.categoryTracking};
  text-transform: uppercase;
}
.kr-gal__name {
  display: block;
  color: ${color.name};
  font-family: ${typography.nameFamily};
  font-size: ${typography.nameSize}px;
  font-weight: ${typography.nameWeight};
  letter-spacing: ${typography.nameTracking};
  white-space: nowrap;
}

/* ── bar: counter, arrows, progress ───────────────────── */
.kr-gal__bar {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: ${spacing.barGap}px;
  margin-top: 68px;
}
.kr-gal__counter {
  margin: 0;
  display: flex;
  align-items: baseline;
  gap: 6px;
  color: ${color.counterTotal};
  font-family: ${typography.counterTotalFamily};
  font-size: ${typography.counterTotalSize}px;
  font-weight: ${typography.counterTotalWeight};
  font-variant-numeric: tabular-nums;
}
.kr-gal__counter-current {
  color: ${color.counterCurrent};
  font-family: ${typography.counterCurrentFamily};
  font-size: ${typography.counterCurrentSize}px;
  font-weight: ${typography.counterCurrentWeight};
  letter-spacing: -0.02em;
  line-height: 1;
}

.kr-gal__controls { display: flex; gap: ${spacing.controlGap}px; }
.kr-gal__arrow {
  width: ${layout.arrowSize}px;
  height: ${layout.arrowSize}px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid ${color.arrowBorder};
  border-radius: 50%;
  background: none;
  color: ${color.arrowIcon};
  cursor: pointer;
  transition: border-color ${timing.hover}ms ${ease}, color ${timing.hover}ms ${ease};
}
.kr-gal__arrow:hover:not(:disabled) {
  border-color: ${color.arrowHoverBorder};
  color: ${color.arrowHoverIcon};
}
.kr-gal__arrow:disabled { color: ${color.arrowDisabled}; opacity: .4; cursor: default; }
.kr-gal__arrow:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* One growing line beats twelve tiny dots. */
.kr-gal__progress {
  margin-top: 22px;
  height: ${layout.progressHeight}px;
  background: ${color.progressTrack};
  overflow: hidden;
}
.kr-gal__progress span {
  display: block;
  height: 100%;
  background: ${color.progressFill};
  transform-origin: left center;
  transform: scaleX(var(--kr-gal-progress, 0));
  transition: transform ${timing.slide}ms ${ease};
}

/* ── lightbox ─────────────────────────────────────────── */
.kr-lightbox {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  background: ${color.lightboxBackdrop};
  opacity: 0;
  visibility: hidden;
  transition:
    opacity ${timing.lightbox}ms ${ease},
    visibility 0s linear ${timing.lightbox}ms;
}
.kr-lightbox--open { opacity: 1; visibility: visible; transition-delay: 0s; }

.kr-lightbox__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 24px;
  flex-shrink: 0;
}
.kr-lightbox__meta { min-width: 0; }
.kr-lightbox__category {
  display: block;
  color: ${color.lightboxCategory};
  font-family: ${typography.categoryFamily};
  font-size: ${typography.categorySize}px;
  font-weight: ${typography.categoryWeight};
  letter-spacing: ${typography.categoryTracking};
  text-transform: uppercase;
}
.kr-lightbox__name {
  display: block;
  margin-top: 5px;
  color: ${color.lightboxText};
  font-family: ${typography.nameFamily};
  font-size: ${typography.nameSize}px;
  font-weight: ${typography.nameWeight};
}
.kr-lightbox__count {
  color: ${color.lightboxMuted};
  font-family: ${typography.counterTotalFamily};
  font-size: ${typography.counterTotalSize}px;
  font-variant-numeric: tabular-nums;
}

.kr-lightbox__stage {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 24px 24px;
}
.kr-lightbox__image {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  display: block;
}

.kr-lightbox__control {
  width: 46px;
  height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid ${color.lightboxControlBorder};
  border-radius: 50%;
  background: none;
  color: ${color.lightboxText};
  cursor: pointer;
  flex-shrink: 0;
  transition: border-color ${timing.hover}ms ${ease}, color ${timing.hover}ms ${ease};
}
.kr-lightbox__control:hover {
  border-color: ${color.lightboxControlHover};
  color: ${color.lightboxControlHover};
}
.kr-lightbox__control:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-lightbox__nav { display: flex; gap: 10px; align-items: center; }

/* ── responsive ───────────────────────────────────────── */
@media (max-width: 1080px) {
  .kr-gal__swiper .swiper-slide { width: ${layout.activeWidthTablet}; }
}
@media (max-width: ${layout.stackBarBelow}px) {
  .kr-gal {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-gal__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-gal__swiper .swiper-slide { width: ${layout.activeWidthMobile}; }
  .kr-gal__frame { aspect-ratio: ${layout.aspectMobile}; }

  /* The label moves beneath the photograph rather than overlapping it —
     small screens have no room to spare for an overlay. */
  .kr-gal__label {
    position: static;
    transform: none;
    opacity: 1;
    margin-top: 16px;
    padding: 0;
    background: none;
    border: 0;
    box-shadow: none;
  }
  .kr-gal__name { white-space: normal; }
  .kr-gal__bar { margin-top: 26px; justify-content: space-between; }
  .kr-gal__expand { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-gal__swiper .swiper-slide,
  .kr-gal__image,
  .kr-gal__label,
  .kr-gal__progress span,
  .kr-lightbox {
    transition: none;
  }
  .swiper-slide-active .kr-gal__frame:hover .kr-gal__image { transform: none; }
}
`;

/** Without JavaScript Swiper never initialises; show the photographs plainly. */
const noscriptCss = `
.kr-gal__swiper .swiper-slide { opacity: 1; transform: none; }
.kr-gal__label { position: static; transform: none; opacity: 1; }
.kr-gal__expand, .kr-gal__bar, .kr-gal__progress, .kr-gal__filters { display: none; }
`;

const template: GalleryTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-gal",
  timing,
  labels,
};

export default template;
