import React, { useState } from "react";
import { Link } from "gatsby";
import { LuArrowRight, LuCheck } from "react-icons/lu";

import type { OverviewTemplate } from "../../templates/overview/default-template";
import useInView from "../shared/useInView";

export type OverviewDetail = {
  key: string;
  label: string;
  /** Null or empty means the client has not confirmed it — the row is omitted. */
  value: string | null;
  icon?: React.ComponentType<{ size?: number; strokeWidth?: number }>;
};

export type OverviewImage = {
  src: string;
  srcSet?: string;
  alt: string;
  position?: string;
};

export type OverviewContent = {
  lead: string;
  /** Paragraphs. Anything past `visibleParagraphs` sits behind Read more. */
  body: string[];
  details: OverviewDetail[];
  amenities: string[];
  mainImage: OverviewImage;
  supportingImage?: OverviewImage;
  primaryCta?: { label: string; href: string };
  secondaryCta?: { label: string; href: string };
};

export type PropertyOverviewProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: OverviewTemplate;
  content: OverviewContent;
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  /** Paragraphs shown before Read more appears. */
  visibleParagraphs?: number;
  /** Amenities shown before View all appears. */
  visibleAmenities?: number;
  detailsLabel?: string;
  amenitiesLabel?: string;
  enabled?: boolean;
};

/**
 * Property-level overview: what this place and community are like.
 *
 * Unit specifics — bedrooms, bathrooms, unit square footage, unit rent — stay
 * in the floor plans section above. Repeating them here would just make the
 * page longer without making it more useful.
 *
 * Every optional field is genuinely optional: an unconfirmed pet policy is
 * omitted entirely rather than rendered as "Pet Policy — N/A", and the grid
 * rebalances around whatever is missing.
 */
export default function PropertyOverview({
  template,
  content,
  heading,
  visibleParagraphs = 2,
  visibleAmenities = 8,
  detailsLabel = "Property Details",
  amenitiesLabel = "Property Amenities",
  enabled = true,
}: PropertyOverviewProps) {
  const { ref, inView } = useInView<HTMLElement>({ threshold: 0.12 });
  const [expanded, setExpanded] = useState(false);
  const [allAmenities, setAllAmenities] = useState(false);

  if (!enabled) return null;

  const root = template.rootClass;

  const details = content.details.filter((detail) => detail.value);
  const paragraphs = expanded ? content.body : content.body.slice(0, visibleParagraphs);
  const hasMoreCopy = content.body.length > visibleParagraphs;

  const amenities = allAmenities
    ? content.amenities
    : content.amenities.slice(0, visibleAmenities);
  const hasMoreAmenities = content.amenities.length > visibleAmenities;

  return (
    <section ref={ref} className={`${root}${inView ? ` ${root}--in` : ""}`}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        <div className={`${root}__content`}>
          {heading}

          <p className={`${root}__lead`}>{content.lead}</p>

          <div className={`${root}__body`}>
            {paragraphs.map((paragraph) => (
              <p key={paragraph.slice(0, 40)}>{paragraph}</p>
            ))}
          </div>

          {hasMoreCopy ? (
            <button
              type="button"
              className={`${root}__more`}
              aria-expanded={expanded}
              onClick={() => setExpanded((open) => !open)}
            >
              {expanded ? "Read less" : "Read more"}
            </button>
          ) : null}

          {details.length ? (
            <>
              <p className={`${root}__sublabel`}>{detailsLabel}</p>
              <ul className={`${root}__details`}>
                {details.map((detail) => {
                  const Icon = detail.icon;
                  return (
                    <li key={detail.key} className={`${root}__detail`}>
                      {Icon ? (
                        <span className={`${root}__detail-icon`} aria-hidden="true">
                          <Icon size={15} strokeWidth={1.5} />
                        </span>
                      ) : null}
                      <span>
                        <span className={`${root}__detail-label`}>{detail.label}</span>
                        <span className={`${root}__detail-value`}>{detail.value}</span>
                      </span>
                    </li>
                  );
                })}
              </ul>
            </>
          ) : null}

          {content.amenities.length ? (
            <>
              <p className={`${root}__sublabel`}>{amenitiesLabel}</p>
              <ul className={`${root}__amenities`}>
                {amenities.map((amenity) => (
                  <li key={amenity} className={`${root}__amenity`}>
                    <span className={`${root}__amenity-icon`} aria-hidden="true">
                      <LuCheck size={15} strokeWidth={2} />
                    </span>
                    {amenity}
                  </li>
                ))}
              </ul>

              {hasMoreAmenities ? (
                <button
                  type="button"
                  className={`${root}__more`}
                  aria-expanded={allAmenities}
                  onClick={() => setAllAmenities((open) => !open)}
                >
                  {allAmenities ? "Show fewer" : "View all amenities"}
                </button>
              ) : null}
            </>
          ) : null}

          {content.primaryCta || content.secondaryCta ? (
            <div className={`${root}__actions`}>
              {content.primaryCta ? (
                <Link className="kr-btn kr-btn--dark" to={content.primaryCta.href}>
                  {content.primaryCta.label}
                  <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
                </Link>
              ) : null}
              {content.secondaryCta ? (
                <Link className="kr-btn kr-btn--outline" to={content.secondaryCta.href}>
                  {content.secondaryCta.label}
                </Link>
              ) : null}
            </div>
          ) : null}
        </div>

        <div className={`${root}__visual`}>
          <div className={`${root}__block`} aria-hidden="true" />
          <span className={`${root}__rule`} aria-hidden="true" />

          <div className={`${root}__main`}>
            <img
              className={`${root}__main-image`}
              src={content.mainImage.src}
              srcSet={content.mainImage.srcSet}
              sizes={content.mainImage.srcSet ? "(max-width: 960px) 92vw, 48vw" : undefined}
              alt={content.mainImage.alt}
              style={
                content.mainImage.position
                  ? { objectPosition: content.mainImage.position }
                  : undefined
              }
              loading="lazy"
              decoding="async"
            />
          </div>

          {content.supportingImage ? (
            <div className={`${root}__inset`}>
              <span className={`${root}__inset-figure`}>
                <img
                  className={`${root}__inset-image`}
                  src={content.supportingImage.src}
                  srcSet={content.supportingImage.srcSet}
                  sizes={content.supportingImage.srcSet ? "(max-width: 960px) 42vw, 22vw" : undefined}
                  alt={content.supportingImage.alt}
                  style={
                    content.supportingImage.position
                      ? { objectPosition: content.supportingImage.position }
                      : undefined
                  }
                  loading="lazy"
                  decoding="async"
                />
              </span>
            </div>
          ) : null}
        </div>
      </div>
    </section>
  );
}
