import React from "react";

import template from "../../config/property-hero--template";
import PropertyMiniHero from "../../modules/property-hero/PropertyMiniHero";
import { photoCount } from "../../modules/property/derive";
import type { PropertyRecord } from "../../modules/property/types";
import { resolveProperty } from "../property/property-images";

export type PropertyHeroXProps = {
  /** The property being viewed. One template, every property. */
  property: PropertyRecord;
};

/**
 * The property page mini hero, configured.
 *
 * Takes a record rather than resolved data so callers pass the same shape the
 * CMS stores; the image key is resolved here.
 */
export default function PropertyHeroX({ property }: PropertyHeroXProps) {
  return (
    <PropertyMiniHero
      template={template}
      property={{
        ...resolveProperty(property),
        /* Counted, never typed. Several bundled records claimed eighteen
           photographs while the gallery rendered eight, so "View 18 Photos"
           broke on the next click. derive.photoCount is the only source now,
           and the CMS cannot write the field back. */
        photoCount: photoCount(property) || property.photoCount,
        rentFrom: property.rentFrom,
      }}
    />
  );
}
