export type PropertyGalleryXProps = {
  /**
   * This property's photographs.
   *
   * Falls back to the shared demo set while the bundled listings have none of
   * their own — but the fallback is now the exception rather than the only
   * path, and a record that carries `images` shows its own building.
   */
  images?: GalleryImage[];
};

/** The property gallery, configured. */
export default function PropertyGalleryX({ images }: PropertyGalleryXProps) {
  return (
    <PropertyGallery
      template={template}
      enabled={galleryEnabled}
      images={images && images.length ? images : demoGallery}
      heading={
        <SectionTitle
          backgroundText="Gallery"
          title="Take a Look Around"
          description="Explore the spaces, details and features that make this property feel like home."
          align="left"
        />
      }
    />
  );
}
